//! Tiny terminal size probe used by the help renderer.
//!
//! Checks stdout, stderr and stdin (in that order) and reports the size of
//! the first one that is attached to a terminal with a non-zero size.

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Width(pub u16);

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Height(pub u16);

fn probe(fd: libc::c_int) -> Option<(Width, Height)> {
    unsafe {
        if libc::isatty(fd) != 1 {
            return None;
        }
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws as *mut libc::winsize) != 0 {
            return None;
        }
        if ws.ws_row > 0 && ws.ws_col > 0 {
            Some((Width(ws.ws_col), Height(ws.ws_row)))
        } else {
            None
        }
    }
}

/// Returns the size of the terminal, if any of the standard streams is one.
pub fn terminal_size() -> Option<(Width, Height)> {
    probe(libc::STDOUT_FILENO)
        .or_else(|| probe(libc::STDERR_FILENO))
        .or_else(|| probe(libc::STDIN_FILENO))
}
EOF
