//! Backslash escape processing for replacement strings.

/// Expands the supported backslash escapes (`\n`, `\r`, `\t`, `\'`, `\"`,
/// `\\`, `\uXXXX` and `\xXX`).  Unknown or malformed escapes are kept as-is.
pub fn unescape(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    let mut rest = input;

    while let Some(pos) = rest.find('\\') {
        out.push_str(&rest[..pos]);
        rest = &rest[pos + 1..];

        let mut it = rest.chars();
        let next = match it.next() {
            Some(c) => c,
            None => {
                // trailing lone backslash
                out.push('\\');
                return out;
            }
        };
        let after = it.as_str();

        let simple = match next {
            'n' => Some('\n'),
            'r' => Some('\r'),
            't' => Some('\t'),
            '\'' => Some('\''),
            '"' => Some('"'),
            '\\' => Some('\\'),
            _ => None,
        };
        if let Some(c) = simple {
            out.push(c);
            rest = after;
            continue;
        }

        let hex_len = match next {
            'u' => Some(4),
            'x' => Some(2),
            _ => None,
        };
        if let Some(n) = hex_len {
            if let Some((c, remaining)) = decode_hex(after, n) {
                out.push(c);
                rest = remaining;
                continue;
            }
        }

        out.push('\\');
        out.push(next);
        rest = after;
    }
    out.push_str(rest);
    out
}

/// Attempts to decode `n` bytes of hex digits at the start of `s`.
///
/// On success, the decoded char is returned together with the remainder of
/// the input.  Note that one extra character following the digits is
/// swallowed as well, mirroring the behaviour of the reference tool.
fn decode_hex(s: &str, n: usize) -> Option<(char, &str)> {
    let digits = s.get(0..n)?;
    let value = u32::from_str_radix(digits, 16).ok()?;
    let c = char::from_u32(value)?;
    let mut it = s.chars();
    // consume n + 1 characters
    let _ = it.nth(n);
    Some((c, it.as_str()))
}

#[cfg(test)]
mod tests {
    use super::unescape;

    #[test]
    fn basics() {
        assert_eq!(unescape("a\\nb"), "a\nb");
        assert_eq!(unescape("\\x41Z"), "A");
        assert_eq!(unescape("\\x41ZY"), "AY");
        assert_eq!(unescape("\\q"), "\\q");
        assert_eq!(unescape("a\\"), "a\\");
        assert_eq!(unescape("\\x+4"), "\u{4}");
        assert_eq!(unescape("\\uD83D"), "\\uD83D");
    }
}
