//! Detection of ambiguous numbered capture references in replacements.

use std::fmt;

#[derive(Debug)]
pub struct AmbiguousCapture {
    original: String,
    /// byte offset of the identifier (just after the `$`)
    ident_start: usize,
    /// byte offset one past the identifier
    ident_end: usize,
    /// number of leading ASCII digits in the identifier
    digits: usize,
}

fn is_cap_letter(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_'
}

/// Walks the replacement in the same way capture expansion does and reports
/// the first `$<digits><letters>` reference, which is almost certainly a
/// mistake (`$1a` is parsed as a group named `1a`).
pub fn check(replacement: &str) -> Result<(), AmbiguousCapture> {
    let bytes = replacement.as_bytes();
    let len = bytes.len();
    let mut i = 0;

    while i < len {
        let dollar = match bytes[i..].iter().position(|&b| b == b'$') {
            Some(p) => i + p,
            None => break,
        };
        i = dollar;
        if i + 1 >= len {
            break;
        }
        match bytes[i + 1] {
            b'$' => {
                i += 2;
            }
            b'{' => match bytes[i + 2..].iter().position(|&b| b == b'}') {
                Some(p) => i = i + 2 + p + 1,
                None => i += 1,
            },
            _ => {
                let start = i + 1;
                let mut end = start;
                while end < len && is_cap_letter(bytes[end]) {
                    end += 1;
                }
                if end == start {
                    i += 1;
                    continue;
                }
                let digits = bytes[start..end]
                    .iter()
                    .take_while(|b| b.is_ascii_digit())
                    .count();
                if digits > 0 && digits < end - start {
                    return Err(AmbiguousCapture {
                        original: replacement.to_owned(),
                        ident_start: start,
                        ident_end: end,
                        digits,
                    });
                }
                i = end;
            }
        }
    }
    Ok(())
}

fn visible(c: char) -> char {
    match c {
        '\n' => '\u{240A}',
        '\r' => '\u{240D}',
        '\t' => '\u{2409}',
        other => other,
    }
}

impl fmt::Display for AmbiguousCapture {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let ident = &self.original[self.ident_start..self.ident_end];
        let (num, tail) = ident.split_at(self.digits);
        writeln!(
            f,
            "The numbered capture group `${}` in the replacement text is ambiguous.",
            num
        )?;
        writeln!(
            f,
            "hint: Use curly braces to disambiguate it `${{{}}}{}`.",
            num, tail
        )?;
        let shown: String = self.original.chars().map(visible).collect();
        writeln!(f, "{}", shown)?;
        let pad = self.original[..self.ident_start].chars().count();
        let width = ident.chars().count();
        write!(f, "{}{}", " ".repeat(pad), "^".repeat(width))
    }
}

impl std::error::Error for AmbiguousCapture {}

#[cfg(test)]
mod tests {
    use super::check;

    #[test]
    fn detects() {
        assert!(check("$1a").is_err());
        assert!(check("${1}a").is_ok());
        assert!(check("$$1a").is_ok());
        assert!(check("$$$1a").is_err());
        assert!(check("${$1a").is_err());
        assert!(check("${x$1a}").is_ok());
        assert!(check("$a1").is_ok());
        assert!(check("$1").is_ok());
    }
}
EOF"}

