//! Error type used throughout the program.

use std::fmt;
use std::path::PathBuf;

use crate::validate::AmbiguousCapture;

#[derive(Debug)]
pub enum Error {
    Regex(regex::Error),
    Io(std::io::Error),
    Persist(tempfile::PersistError),
    InvalidPath(PathBuf),
    Capture(AmbiguousCapture),
    FailedJobs(Vec<(PathBuf, Error)>),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Regex(e) => write!(f, "invalid regex {}", e),
            Error::Io(e) => write!(f, "{}", e),
            Error::Persist(e) => write!(f, "{}", e),
            Error::InvalidPath(p) => write!(f, "invalid path: {}", p.display()),
            Error::Capture(e) => write!(f, "{}", e),
            Error::FailedJobs(jobs) => {
                f.write_str("Failed processing some inputs\n")?;
                for (path, err) in jobs {
                    writeln!(f, "    {}: {}", path.display(), err)?;
                }
                Ok(())
            }
        }
    }
}

impl std::error::Error for Error {}

impl From<regex::Error> for Error {
    fn from(e: regex::Error) -> Self {
        Error::Regex(e)
    }
}

impl From<std::io::Error> for Error {
    fn from(e: std::io::Error) -> Self {
        Error::Io(e)
    }
}

impl From<tempfile::PersistError> for Error {
    fn from(e: tempfile::PersistError) -> Self {
        Error::Persist(e)
    }
}

impl From<AmbiguousCapture> for Error {
    fn from(e: AmbiguousCapture) -> Self {
        Error::Capture(e)
    }
}

pub type Result<T, E = Error> = std::result::Result<T, E>;
