//! Regex construction and replacement.

use regex::bytes::{Regex, RegexBuilder};
use std::borrow::Cow;

use crate::error::Result;
use crate::{unescape, validate};

pub struct Replacer {
    regex: Regex,
    replace_with: Vec<u8>,
    literal: bool,
    limit: usize,
}

impl Replacer {
    pub fn new(
        find: String,
        replace_with: String,
        literal: bool,
        flags: Option<String>,
        limit: usize,
    ) -> Result<Self> {
        let (pattern, replace_with) = if literal {
            (regex::escape(&find), replace_with.into_bytes())
        } else {
            validate::check(&replace_with)?;
            (find, unescape::unescape(&replace_with).into_bytes())
        };

        let mut builder = RegexBuilder::new(&pattern);
        builder.multi_line(true);

        if let Some(flags) = flags.as_deref() {
            for c in flags.chars() {
                match c {
                    'c' => {
                        builder.case_insensitive(false);
                    }
                    'i' => {
                        builder.case_insensitive(true);
                    }
                    'm' => {}
                    'e' => {
                        builder.multi_line(false);
                    }
                    's' => {
                        if !flags.contains('m') {
                            builder.multi_line(false);
                        }
                        builder.dot_matches_new_line(true);
                    }
                    'w' => {
                        // starts over from a fresh builder
                        builder = RegexBuilder::new(&format!("\\b{}\\b", pattern));
                    }
                    _ => {}
                }
            }
        }

        let regex = builder.build()?;
        Ok(Replacer {
            regex,
            replace_with,
            literal,
            limit,
        })
    }

    pub fn replace<'a>(&self, haystack: &'a [u8]) -> Cow<'a, [u8]> {
        if self.literal {
            self.regex.replacen(
                haystack,
                self.limit,
                regex::bytes::NoExpand(&self.replace_with),
            )
        } else {
            self.regex
                .replacen(haystack, self.limit, self.replace_with.as_slice())
        }
    }
}
EOF"}

